{
  "title": "A hungrier day in Kyoto",
  "summary": "Rin gets her wish: a market wander, a proper lunch, and an evening of snacks and yakitori, with the temple kept front and centre.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Still the anchor. Shoes off, phone down, eyes up before the eating begins."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Rin wanted to eat her way through the day, so we start with the market’s street food."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "A cheap, proper bowl for lunch. Budget-friendly and very Kyoto."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A slow walk through Gion to settle lunch before the evening snacks."
    },
    {
      "poi_id": "p21",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with sticks and smoke. Splurge taste, street-level price."
    }
  ]
}
